#!/usr/bin/env node
/**
 * Generates the icon modules in src/icons/for/ from src/icons/icons.json (Material Symbols paths).
 *
 *   node scripts/gen-icons.mjs          write src/icons/for/<key>.tsx
 *   node scripts/gen-icons.mjs --check  fail if any generated file is missing or stale
 *
 * A component (or a shared helper) imports its icons by name from `icons/for/<key>`:
 *
 *   import { ArrowForward, Close } from '../../icons/for/sc-modal';
 *
 * The script scans src/ for those imports and writes one self-contained module per key with
 * exactly the names imported from it, its own copy of the small SVG wrapper and no other import
 * than Stencil's `h`. Each key is imported by one file only, so the bundler inlines the module
 * into that component: a component pays for the icons it uses and nothing else, with no shared
 * icon chunk (decision W9). Shared chunks would hold every icon any of their importers uses.
 *
 * Importable names:
 *   - every icon in icons.json "icons" (a component: <ArrowForward />)
 *   - <Name>Path for an icon's raw path string, for an SVG built in the DOM (e.g. ChevronForwardPath)
 *   - every set in icons.json "sets" (a by-name component, e.g. <ButtonIcon name="search" />)
 *     and its name type (e.g. ButtonIconName)
 *   - Spinner (the 270° arc, not a Material Symbol)
 */
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const src = join(root, 'src');
const outDir = join(src, 'icons', 'for');
const manifest = JSON.parse(readFileSync(join(src, 'icons', 'icons.json'), 'utf8'));
const check = process.argv.includes('--check');

const walk = (dir) =>
  readdirSync(dir).flatMap((name) => {
    const p = join(dir, name);
    return statSync(p).isDirectory() ? walk(p) : [p];
  });

/** key → { names: Set, importers: string[] } */
const wanted = new Map();
const importRe = /import\s+(type\s+)?\{([^}]*)\}\s+from\s+['"](?:\.\.?\/)+icons\/for\/([\w-]+)['"]/g;
// components.d.ts (generated by Stencil) only imports the name types; it never adds a chunk.
for (const file of walk(src).filter((f) => /\.tsx?$/.test(f) && !f.startsWith(join(src, 'icons')) && !/\.(spec|e2e)\.tsx?$/.test(f) && !f.endsWith('components.d.ts'))) {
  for (const m of readFileSync(file, 'utf8').matchAll(importRe)) {
    const entry = wanted.get(m[3]) ?? { names: new Set(), importers: [] };
    for (const name of m[2].split(',').map((n) => n.trim().replace(/^type\s+/, '').split(/\s+as\s+/)[0]).filter(Boolean)) entry.names.add(name);
    entry.importers.push(relative(root, file));
    wanted.set(m[3], entry);
  }
}

const problems = [];
const typeNames = new Map(Object.entries(manifest.sets).map(([name, set]) => [set.type, name]));

function iconLine(name) {
  const i = manifest.icons[name];
  const doc = `/** ${i.note} Material Symbols \`${i.material}\`, ${i.fill ? 'Filled' : 'Outlined'}. ${i.mirror ? 'Mirrors in right-to-left.' : 'Never mirrored.'} */`;
  return `${doc}\nexport const ${name} = icon('${i.d}'${i.mirror ? ', true' : ''});`;
}

function render(key, { names, importers }) {
  const out = [];
  let needsIcon = false;
  const body = [];
  const sorted = [...names].sort();
  for (const name of sorted) {
    if (manifest.icons[name]) {
      needsIcon = true;
      body.push(iconLine(name));
    } else if (name.endsWith('Path') && manifest.icons[name.slice(0, -4)]) {
      const i = manifest.icons[name.slice(0, -4)];
      body.push(`/** Material Symbols \`${i.material}\` path, for an SVG built in the DOM (viewBox "0 -960 960 960", fill currentColor). ${i.mirror ? 'Mirrors in right-to-left.' : 'Never mirrored.'} */\nexport const ${name} = '${i.d}';`);
    } else if (manifest.sets[name]) {
      needsIcon = true;
      const set = manifest.sets[name];
      const pairs = Object.entries(set.names);
      const filled = Array.isArray(pairs[0][1]);
      const entry = (v) => {
        const i = manifest.icons[v];
        if (!i) problems.push(`${key}: set ${name} names unknown icon ${v}`);
        return `'${i?.d}'`;
      };
      const mirror = (v) => !!manifest.icons[Array.isArray(v) ? v[0] : v]?.mirror;
      body.push(
        [
          `const ${name}Set: Record<string, [${filled ? 'outlined: string, filled: string' : 'd: string'}, mirror: boolean]> = {`,
          // A Filled path identical to the Outlined one is written once ('' below means "the same").
          ...pairs.map(([n, v]) => `  '${n}': [${Array.isArray(v) ? [entry(v[0]), entry(v[1]) === entry(v[0]) ? "''" : entry(v[1])].join(', ') : entry(v)}, ${mirror(v)}],`),
          '};',
          '',
          `/** ${set.note} */`,
          `export type ${set.type} = ${pairs.map(([n]) => `'${n}'`).join(' | ')};`,
          '',
          `/** ${set.note} Renders nothing for a name outside the set. */`,
          `export const ${name}: FunctionalComponent<IconProps & { name?: string | null${filled ? '; filled?: boolean' : ''} }> = ({ name, ${filled ? 'filled, ' : ''}...rest }) => {`,
          `  const entry = name ? ${name}Set[name] : undefined;`,
          '  if (!entry) return null;',
          `  const Icon = icon(${filled ? '(filled && entry[1]) || entry[0], entry[2]' : 'entry[0], entry[1]'});`,
          '  return <Icon {...rest} />;',
          '};',
        ].join('\n'),
      );
    } else if (typeNames.has(name)) {
      if (!names.has(typeNames.get(name))) problems.push(`${key}: import ${typeNames.get(name)} with ${name}`);
    } else if (name === 'Spinner') {
      body.push(
        [
          '/** Spinner: a 270° arc, 2.5px stroke, round caps, no track (Paper sc-spinner, node 4RS-0). Not a Material Symbol. Turned by `.spin`. Never mirrored. */',
          'export const Spinner: FunctionalComponent<IconProps> = ({ class: extra }) => (',
          '  <svg class={{ icon: true, [extra ?? \'\']: !!extra }} viewBox="0 0 24 24" width="24" height="24" fill="none" aria-hidden="true" focusable="false">',
          '    <circle cx="12" cy="12" r="9" transform="rotate(-90 12 12)" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-dasharray="42.41 56.55" />',
          '  </svg>',
          ');',
        ].join('\n'),
      );
    } else {
      problems.push(`${key}: unknown icon ${name} (imported by ${importers.join(', ')})`);
    }
  }
  out.push(`/* Generated by scripts/gen-icons.mjs from src/icons/icons.json. Do not edit: run \`npm run icons\`. */`);
  out.push(`/* Imported by: ${importers.join(', ')} */`);
  const needsJsx = needsIcon || names.has('Spinner');
  if (needsJsx) {
    out.push(`import { FunctionalComponent, h } from '@stencil/core';`);
    out.push('');
    out.push('interface IconProps {\n  /** Extra classes for the <svg>. */\n  class?: string;\n}');
  }
  if (needsIcon) {
    out.push('');
    out.push(
      [
        '/** Material Symbols on the 960 grid, in currentColor; decorative. `mirror` adds `icon-directional`. */',
        'const icon =',
        '  (d: string, mirror?: boolean): FunctionalComponent<IconProps> =>',
        '  ({ class: extra }) => (',
        '    <svg class={{ \'icon\': true, \'icon-directional\': !!mirror, [extra ?? \'\']: !!extra }} viewBox="0 -960 960 960" width="24" height="24" fill="currentColor" aria-hidden="true" focusable="false">',
        '      <path d={d} />',
        '    </svg>',
        '  );',
      ].join('\n'),
    );
  }
  for (const b of body) out.push('', b);
  return out.join('\n') + '\n';
}

for (const [key, entry] of wanted) {
  if (entry.importers.length > 1) problems.push(`icons/for/${key} is imported by ${entry.importers.length} files (${entry.importers.join(', ')}): give each file its own key, or it becomes a shared chunk`);
}

const expected = new Map([...wanted].map(([key, entry]) => [join(outDir, `${key}.tsx`), render(key, entry)]));
if (problems.length) {
  console.error(`gen-icons: ${problems.length} problem(s):\n  ${problems.join('\n  ')}`);
  process.exit(1);
}

const existing = existsSync(outDir) ? readdirSync(outDir).filter((f) => f.endsWith('.tsx')).map((f) => join(outDir, f)) : [];
if (check) {
  const stale = [...expected].filter(([file, text]) => !existsSync(file) || readFileSync(file, 'utf8') !== text).map(([f]) => relative(root, f));
  const extra = existing.filter((f) => !expected.has(f)).map((f) => relative(root, f));
  if (stale.length || extra.length) {
    console.error(`gen-icons --check: run \`npm run icons\`. Stale: ${stale.join(', ') || 'none'}. Unused: ${extra.join(', ') || 'none'}.`);
    process.exit(1);
  }
  console.log(`gen-icons --check: ${expected.size} icon modules up to date.`);
} else {
  mkdirSync(outDir, { recursive: true });
  for (const f of existing) if (!expected.has(f)) rmSync(f);
  for (const [file, text] of expected) writeFileSync(file, text);
  console.log(`gen-icons: wrote ${expected.size} icon modules to ${relative(root, outDir)}.`);
}
